-- ============================================================================
-- TableBite / ARM Coffee Place - Supabase Seed Data
-- Run this in Supabase SQL Editor after running supabase-schema.sql
-- ============================================================================

-- 1. Seed Categories
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, icon = EXCLUDED.icon, display_order = EXCLUDED.display_order;

-- 2. Seed Products
ON CONFLICT (id) DO UPDATE SET 
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  base_price = EXCLUDED.base_price,
  image_url = EXCLUDED.image_url,
  portions = EXCLUDED.portions,
  addons = EXCLUDED.addons;

-- 3. Seed 16 Tables with Cryptographic QR Tokens
ON CONFLICT (id) DO NOTHING;

-- 4. Seed Restaurant Settings for ARM Coffee Place
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
